/// <summary>
/// Validate FiscalCalendarPeriod table record on saving
/// </summary>
/// <returns>true or false</returns>
public boolean validateWrite()
{
    boolean ret = next validateWrite();

    if (ret)
    {
        if (this.METNoOfWeeksForPeriod == METNoOfWeeksForPeriod::Empty)
        {
            ret = checkFailed("@MET:SetNoOfWeeks");
        }
    }

    return ret;
}

/// <summary>
/// FiscalCalendarperiod table insert extension
/// </summary>
public void insert()
{
    this.METNoOfWeeksForPeriod = METNoOfWeeksForPeriod::Empty;
    next insert();
}

/// <summary>
/// Bug 289018: CB201 - Volumetric Tier Rebates - Calculate Rate picking up incorrect dates
/// Refactor code to find calendar month
/// </summary>
/// <param name = "_fromDate">From date</param>
/// <param name = "_toDate">To date</param>
/// <param name = "_calendarId">Fiscal calendar id</param>
/// <returns>4 or 5 weeks for the period</returns>
public static int metCalendarMonth(FromDate _fromDate, ToDate _toDate, FiscalCalendarID _calendarId)
{
    int ret;
    FiscalCalendarPeriod fiscalCalendarPeriod;
    FiscalCalendar fiscalCal;
    FiscalCalendarYear fiscalCalYear;

    // Find calendar month
    select firstonly METNoOfWeeksForPeriod from fiscalCalendarPeriod
                exists join fiscalCalYear
            where fiscalCalendarPeriod.FiscalCalendarYear == fiscalCalYear.RecId
                exists join fiscalCal
                    where fiscalCal.RecId == fiscalCalYear.FiscalCalendar
                    && fiscalCal.CalendarId == _calendarId
                    && fiscalCalendarPeriod.Type == FiscalPeriodType::Operating
                    && ((fiscalCalendarPeriod.StartDate >= _fromDate && fiscalCalendarPeriod.StartDate <= _toDate) ||
                    (fiscalCalendarPeriod.EndDate >= _fromDate && fiscalCalendarPeriod.EndDate <= _toDate) ||
                    (fiscalCalendarPeriod.startDate <= _fromDate && fiscalCalendarPeriod.endDate >= _toDate));

    int calendarMonth = 0;

    if (fiscalCalendarPeriod.METNoOfWeeksForPeriod == METNoOfWeeksForPeriod::Five)
    {
        calendarMonth = 5;
    }
    else if (fiscalCalendarPeriod.METNoOfWeeksForPeriod == METNoOfWeeksForPeriod::Four)
    {
        calendarMonth = 4;
    }
    else if (fiscalCalendarPeriod.METNoOfWeeksForPeriod == METNoOfWeeksForPeriod::Empty)
    {
        throw error("@MET:SetNoOfWeeks");
    }

    return calendarMonth;
}
